#!/usr/bin/env bash
# Rich demo data for the local stack: the population of the three units of
# Yayasan Teratai Putih (SD, SMP, SMK) and the data of every module on top of
# it, generated by scripts/seed/demo/*.mjs. Run after the base seeds
# (scripts/run-all-seeds.sh or the local equivalent). Idempotent: fixed ids,
# ON CONFLICT DO NOTHING. Needs the whole local stack up, not just postgres:
# 22_teacher_evaluation.mjs asks the evaluation service to bootstrap its
# default forms (GET /forms) before writing the evaluations.
#
#   ./scripts/seed-demo.sh            # every generator
#   ./scripts/seed-demo.sh 01 02      # only these
set -euo pipefail
cd "$(dirname "$0")/.."

COMPOSE=(docker compose -f docker-compose.yml -f docker-compose.local.yml --env-file .env.local)
OUT="$(mktemp -d)"
trap 'rm -rf "$OUT"' EXIT

node scripts/seed/demo/run.mjs "$OUT" "$@"
for f in "$OUT"/*.sql; do
  db="$(basename "$f" .sql)"; db="${db#*_}"
  printf -- '--> %-34s ' "$(basename "$f")"
  "${COMPOSE[@]}" exec -T postgres psql -U "${POSTGRES_USER:-teratai}" -d "$db" -v ON_ERROR_STOP=1 -q < "$f" >/dev/null
  echo ok
done
